(function(root){
'use strict';
const b64=b=>{let s='';for(const x of new Uint8Array(b))s+=String.fromCharCode(x);return btoa(s)},un64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function keyFor(password,salt){if(typeof password!=='string'||password.length<12)throw Error('Use a reference-vault passphrase of at least 12 characters');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encrypt(value,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await keyFor(password,salt),bytes=new TextEncoder().encode(JSON.stringify(value)),ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);return {format:'medannotate-private-references',version:1,kdf:'PBKDF2-SHA256',iterations:310000,salt:b64(salt),iv:b64(iv),ciphertext:b64(ciphertext)}}
async function decrypt(envelope,password){if(envelope.format!=='medannotate-private-references'||envelope.version!==1||envelope.iterations!==310000)throw Error('Unsupported reference vault');try{const salt=un64(envelope.salt),iv=un64(envelope.iv);if(salt.length!==16||iv.length!==12)throw Error('Invalid vault');const key=await keyFor(password,salt),bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,un64(envelope.ciphertext));return JSON.parse(new TextDecoder().decode(bytes))}catch{throw Error('Wrong passphrase or damaged reference vault')}}
function boxesFromOCR(data,width,height,scale=1){const words=data.words||((data.blocks||[]).flatMap(b=>b.paragraphs||[]).flatMap(p=>p.lines||[]).flatMap(l=>l.words||[]));return words.filter(w=>w.confidence>=25&&/[a-z0-9]{2,}/i.test(String(w.text||''))).map(w=>({x0:Math.max(0,Math.floor(w.bbox.x0/scale)-3),y0:Math.max(0,Math.floor(w.bbox.y0/scale)-3),x1:Math.min(width,Math.ceil(w.bbox.x1/scale)+3),y1:Math.min(height,Math.ceil(w.bbox.y1/scale)+3)})).filter(b=>b.x1>b.x0&&b.y1>b.y0)}
function redact(c,regions){if(c.mask.some(x=>x>0))throw Error('Privacy edits must be completed before annotation');let fill=Infinity;for(const x of c.data)fill=Math.min(fill,x);let count=0;for(const r of regions){if(!Number.isInteger(r.k)||r.k<0||r.k>=c.dims[2])throw Error('Invalid redaction slice');for(const b of r.boxes){for(let y=Math.max(0,Math.floor(b.y0));y<Math.min(c.dims[1],Math.ceil(b.y1));y++)for(let x=Math.max(0,Math.floor(b.x0));x<Math.min(c.dims[0],Math.ceil(b.x1));x++){c.data[x+c.dims[0]*(y+c.dims[1]*r.k)]=fill;count++}}}return count}
function referenceCSV(records){const cell=x=>{let v=String(x??'');if(/^[\s]*[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'},fields=['caseId','subjectCode','originalName','patientId','patientName','issuer','studyUID','seriesUID','sources','created'];return [fields,...records.map(r=>fields.map(f=>Array.isArray(r[f])?r[f].join(' | '):r[f]))].map(row=>row.map(cell).join(',')).join('\r\n')}
const api={encrypt,decrypt,boxesFromOCR,redact,referenceCSV};root.MedPrivacy=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
